import manifest from '../data/image-manifest.json';
import { imageVariant } from '../lib/paths';

// Responsive image for anything in public/portfolio (generated by
// `npm run images`): AVIF with WebP fallback, srcset/sizes, and intrinsic
// width/height so the layout doesn't shift while images load.
export default function Picture({ src, alt, sizes = '100vw', loading = 'lazy', className }) {
  const info = manifest[src];
  if (!info) throw new Error(`Image "${src}" is not in image-manifest.json — run npm run images`);
  const srcSet = (ext) => info.widths.map((w) => `${imageVariant(src, w, ext)} ${w}w`).join(', ');
  const largest = info.widths.at(-1);

  return (
    <picture>
      <source type="image/avif" srcSet={srcSet('avif')} sizes={sizes} />
      <img
        className={className}
        src={imageVariant(src, largest, 'webp')}
        srcSet={srcSet('webp')}
        sizes={sizes}
        width={info.width}
        height={info.height}
        alt={alt}
        loading={loading}
        decoding="async"
      />
    </picture>
  );
}

// A JPEG for places that need one URL in a widely supported format (share images).
export const shareImage = (src) => {
  const info = manifest[src];
  return info ? imageVariant(src, info.widths.at(-1), 'jpg') : undefined;
};

export const imageRatio = (src) => {
  const info = manifest[src];
  return info ? info.width / info.height : 1;
};
